{"output": "from collections import Counter


def transform(grid):
    """Recolor the full-length horizontal/vertical rails to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rail_color = next(v for v, n in Counter(x for row in grid for x in row).items() if v != background and n > min(h, w))
    full_rows = [r for r in range(h) if all(x == rail_color for x in grid[r])]
    full_cols = [c for c in range(w) if all(grid[r][c] == rail_color for r in range(h))]
    for r in full_rows:
        for c in range(w):
            out[r][c] = 2
    for c in full_cols:
        for r in range(h):
            if r not in full_rows:
                out[r][c] = 2
    # Where full row and column rails intersect, preserve the original intersection.
    for r in full_rows:
        for c in full_cols:
            out[r][c] = grid[r][c]
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}
